/*
 * wm2000.c  --  WM2000 ALSA Soc Audio driver
 *
 * Copyright 2008-2011 Wolfson Microelectronics PLC.
 *
 * Author: Mark Brown <broonie@opensource.wolfsonmicro.com>
 *
 * The download image for the WM2000 will be requested as
 * 'wm2000_anc.bin' by default (overridable via platform data) at
 * runtime and is expected to be in flat binary format.  This is
 * generated by Wolfson configuration tools and includes
 * system-specific calibration information.  If supplied as a
 * sequence of ASCII-encoded hexidecimal bytes this can be converted
 * into a flat binary with a command such as this on the command line:
 *
 * perl -e 'while (<>) { s/[\r\n]+// ; printf("%c", hex($_)); }'
 *                 < file  > wm2000_anc.bin
 */

// Dependencies originally included from Linux, ALSA SoC, sound/wm2000.h,
// and local "wm2000.h" headers are referenced as external items.

use core::ffi::{c_char, c_int, c_uint, c_ulong, c_void};
use core::ptr;

const WM2000_NUM_SUPPLIES: usize = 3;

static wm2000_supplies: [*const c_char; WM2000_NUM_SUPPLIES] = [
    b"SPKVDD\0".as_ptr() as *const c_char,
    b"DBVDD\0".as_ptr() as *const c_char,
    b"DCVDD\0".as_ptr() as *const c_char,
];

#[repr(C)]
#[derive(Copy, Clone, PartialEq, Eq)]
enum wm2000_anc_mode {
    ANC_ACTIVE = 0,
    ANC_BYPASS = 1,
    ANC_STANDBY = 2,
    ANC_OFF = 3,
}

#[repr(C)]
struct wm2000_priv {
    i2c: *mut i2c_client,
    regmap: *mut regmap,
    mclk: *mut clk,

    supplies: [regulator_bulk_data; WM2000_NUM_SUPPLIES],

    anc_mode: wm2000_anc_mode,

    anc_active: c_uint,
    anc_eng_ena: c_uint,
    spk_ena: c_uint,

    speech_clarity: c_uint,

    anc_download_size: c_int,
    anc_download: *mut c_char,

    lock: mutex,
}

unsafe fn wm2000_write(i2c: *mut i2c_client, reg: c_uint, value: c_uint) -> c_int {
    let wm2000 = i2c_get_clientdata(i2c) as *mut wm2000_priv;
    regmap_write((*wm2000).regmap, reg, value)
}

unsafe fn wm2000_reset(wm2000: *mut wm2000_priv) {
    let i2c = (*wm2000).i2c;

    wm2000_write(i2c, WM2000_REG_SYS_CTL2, WM2000_ANC_ENG_CLR);
    wm2000_write(i2c, WM2000_REG_SYS_CTL2, WM2000_RAM_CLR);
    wm2000_write(i2c, WM2000_REG_ID1, 0);

    (*wm2000).anc_mode = wm2000_anc_mode::ANC_OFF;
}

unsafe fn wm2000_poll_bit(i2c: *mut i2c_client, reg: c_uint, mask: u8) -> c_int {
    let wm2000 = i2c_get_clientdata(i2c) as *mut wm2000_priv;
    let mut timeout: c_int = 4000;
    let mut val: c_uint = 0;

    regmap_read((*wm2000).regmap, reg, &mut val);

    while (val & mask as c_uint) == 0 && {
        timeout -= 1;
        timeout != 0
    } {
        msleep(1);
        regmap_read((*wm2000).regmap, reg, &mut val);
    }

    if timeout == 0 {
        0
    } else {
        1
    }
}

unsafe fn wm2000_power_up(i2c: *mut i2c_client, analogue: c_int) -> c_int {
    let wm2000 = dev_get_drvdata(&mut (*i2c).dev) as *mut wm2000_priv;
    let rate: c_ulong;
    let mut val: c_uint = 0;
    let mut ret: c_int;

    if WARN_ON((*wm2000).anc_mode != wm2000_anc_mode::ANC_OFF) != 0 {
        return -EINVAL;
    }

    dev_dbg(&mut (*i2c).dev, b"Beginning power up\n\0".as_ptr() as *const c_char);

    ret = regulator_bulk_enable(WM2000_NUM_SUPPLIES as c_int, (*wm2000).supplies.as_mut_ptr());
    if ret != 0 {
        dev_err(&mut (*i2c).dev, b"Failed to enable supplies: %d\n\0".as_ptr() as *const c_char, ret);
        return ret;
    }

    rate = clk_get_rate((*wm2000).mclk);
    if rate <= 13500000 {
        dev_dbg(&mut (*i2c).dev, b"Disabling MCLK divider\n\0".as_ptr() as *const c_char);
        wm2000_write(i2c, WM2000_REG_SYS_CTL2, WM2000_MCLK_DIV2_ENA_CLR);
    } else {
        dev_dbg(&mut (*i2c).dev, b"Enabling MCLK divider\n\0".as_ptr() as *const c_char);
        wm2000_write(i2c, WM2000_REG_SYS_CTL2, WM2000_MCLK_DIV2_ENA_SET);
    }

    wm2000_write(i2c, WM2000_REG_SYS_CTL2, WM2000_ANC_ENG_CLR);
    wm2000_write(i2c, WM2000_REG_SYS_CTL2, WM2000_ANC_ENG_SET);

    /* Wait for ANC engine to become ready */
    if wm2000_poll_bit(i2c, WM2000_REG_ANC_STAT, WM2000_ANC_ENG_IDLE as u8) == 0 {
        dev_err(&mut (*i2c).dev, b"ANC engine failed to reset\n\0".as_ptr() as *const c_char);
        regulator_bulk_disable(WM2000_NUM_SUPPLIES as c_int, (*wm2000).supplies.as_mut_ptr());
        return -ETIMEDOUT;
    }

    if wm2000_poll_bit(i2c, WM2000_REG_SYS_STATUS, WM2000_STATUS_BOOT_COMPLETE as u8) == 0 {
        dev_err(&mut (*i2c).dev, b"ANC engine failed to initialise\n\0".as_ptr() as *const c_char);
        regulator_bulk_disable(WM2000_NUM_SUPPLIES as c_int, (*wm2000).supplies.as_mut_ptr());
        return -ETIMEDOUT;
    }

    wm2000_write(i2c, WM2000_REG_SYS_CTL2, WM2000_RAM_SET);

    /* Open code download of the data since it is the only bulk
     * write we do. */
    dev_dbg(
        &mut (*i2c).dev,
        b"Downloading %d bytes\n\0".as_ptr() as *const c_char,
        (*wm2000).anc_download_size - 2,
    );

    ret = i2c_master_send(i2c, (*wm2000).anc_download, (*wm2000).anc_download_size);
    if ret < 0 {
        dev_err(&mut (*i2c).dev, b"i2c_transfer() failed: %d\n\0".as_ptr() as *const c_char, ret);
        regulator_bulk_disable(WM2000_NUM_SUPPLIES as c_int, (*wm2000).supplies.as_mut_ptr());
        return ret;
    }
    if ret != (*wm2000).anc_download_size {
        dev_err(
            &mut (*i2c).dev,
            b"i2c_transfer() failed, %d != %d\n\0".as_ptr() as *const c_char,
            ret,
            (*wm2000).anc_download_size,
        );
        regulator_bulk_disable(WM2000_NUM_SUPPLIES as c_int, (*wm2000).supplies.as_mut_ptr());
        return -EIO;
    }

    dev_dbg(&mut (*i2c).dev, b"Download complete\n\0".as_ptr() as *const c_char);

    if analogue != 0 {
        wm2000_write(i2c, WM2000_REG_ANA_VMID_PU_TIME, 248 / 4);

        wm2000_write(
            i2c,
            WM2000_REG_SYS_MODE_CNTRL,
            WM2000_MODE_ANA_SEQ_INCLUDE | WM2000_MODE_MOUSE_ENABLE | WM2000_MODE_THERMAL_ENABLE,
        );
    } else {
        wm2000_write(
            i2c,
            WM2000_REG_SYS_MODE_CNTRL,
            WM2000_MODE_MOUSE_ENABLE | WM2000_MODE_THERMAL_ENABLE,
        );
    }

    ret = regmap_read((*wm2000).regmap, WM2000_REG_SPEECH_CLARITY, &mut val);
    if ret != 0 {
        dev_err(&mut (*i2c).dev, b"Unable to read Speech Clarity: %d\n\0".as_ptr() as *const c_char, ret);
        regulator_bulk_disable(WM2000_NUM_SUPPLIES as c_int, (*wm2000).supplies.as_mut_ptr());
        return ret;
    }
    if (*wm2000).speech_clarity != 0 {
        val |= WM2000_SPEECH_CLARITY;
    } else {
        val &= !WM2000_SPEECH_CLARITY;
    }
    wm2000_write(i2c, WM2000_REG_SPEECH_CLARITY, val);

    wm2000_write(i2c, WM2000_REG_SYS_START0, 0x33);
    wm2000_write(i2c, WM2000_REG_SYS_START1, 0x02);

    wm2000_write(i2c, WM2000_REG_SYS_CTL2, WM2000_ANC_INT_N_CLR);

    if wm2000_poll_bit(i2c, WM2000_REG_SYS_STATUS, WM2000_STATUS_MOUSE_ACTIVE as u8) == 0 {
        dev_err(&mut (*i2c).dev, b"Timed out waiting for device\n\0".as_ptr() as *const c_char);
        regulator_bulk_disable(WM2000_NUM_SUPPLIES as c_int, (*wm2000).supplies.as_mut_ptr());
        return -ETIMEDOUT;
    }

    dev_dbg(&mut (*i2c).dev, b"ANC active\n\0".as_ptr() as *const c_char);
    if analogue != 0 {
        dev_dbg(&mut (*i2c).dev, b"Analogue active\n\0".as_ptr() as *const c_char);
    }
    (*wm2000).anc_mode = wm2000_anc_mode::ANC_ACTIVE;

    0
}

unsafe fn wm2000_power_down(i2c: *mut i2c_client, analogue: c_int) -> c_int {
    let wm2000 = dev_get_drvdata(&mut (*i2c).dev) as *mut wm2000_priv;

    if analogue != 0 {
        wm2000_write(i2c, WM2000_REG_ANA_VMID_PD_TIME, 248 / 4);
        wm2000_write(
            i2c,
            WM2000_REG_SYS_MODE_CNTRL,
            WM2000_MODE_ANA_SEQ_INCLUDE | WM2000_MODE_POWER_DOWN,
        );
    } else {
        wm2000_write(i2c, WM2000_REG_SYS_MODE_CNTRL, WM2000_MODE_POWER_DOWN);
    }

    if wm2000_poll_bit(i2c, WM2000_REG_SYS_STATUS, WM2000_STATUS_POWER_DOWN_COMPLETE as u8) == 0 {
        dev_err(&mut (*i2c).dev, b"Timeout waiting for ANC power down\n\0".as_ptr() as *const c_char);
        return -ETIMEDOUT;
    }

    if wm2000_poll_bit(i2c, WM2000_REG_ANC_STAT, WM2000_ANC_ENG_IDLE as u8) == 0 {
        dev_err(&mut (*i2c).dev, b"Timeout waiting for ANC engine idle\n\0".as_ptr() as *const c_char);
        return -ETIMEDOUT;
    }

    regulator_bulk_disable(WM2000_NUM_SUPPLIES as c_int, (*wm2000).supplies.as_mut_ptr());

    dev_dbg(&mut (*i2c).dev, b"powered off\n\0".as_ptr() as *const c_char);
    (*wm2000).anc_mode = wm2000_anc_mode::ANC_OFF;

    0
}

unsafe fn wm2000_enter_bypass(i2c: *mut i2c_client, analogue: c_int) -> c_int {
    let wm2000 = dev_get_drvdata(&mut (*i2c).dev) as *mut wm2000_priv;

    if WARN_ON((*wm2000).anc_mode != wm2000_anc_mode::ANC_ACTIVE) != 0 {
        return -EINVAL;
    }

    if analogue != 0 {
        wm2000_write(
            i2c,
            WM2000_REG_SYS_MODE_CNTRL,
            WM2000_MODE_ANA_SEQ_INCLUDE | WM2000_MODE_THERMAL_ENABLE | WM2000_MODE_BYPASS_ENTRY,
        );
    } else {
        wm2000_write(
            i2c,
            WM2000_REG_SYS_MODE_CNTRL,
            WM2000_MODE_THERMAL_ENABLE | WM2000_MODE_BYPASS_ENTRY,
        );
    }

    if wm2000_poll_bit(i2c, WM2000_REG_SYS_STATUS, WM2000_STATUS_ANC_DISABLED as u8) == 0 {
        dev_err(&mut (*i2c).dev, b"Timeout waiting for ANC disable\n\0".as_ptr() as *const c_char);
        return -ETIMEDOUT;
    }

    if wm2000_poll_bit(i2c, WM2000_REG_ANC_STAT, WM2000_ANC_ENG_IDLE as u8) == 0 {
        dev_err(&mut (*i2c).dev, b"Timeout waiting for ANC engine idle\n\0".as_ptr() as *const c_char);
        return -ETIMEDOUT;
    }

    wm2000_write(i2c, WM2000_REG_SYS_CTL1, WM2000_SYS_STBY);
    wm2000_write(i2c, WM2000_REG_SYS_CTL2, WM2000_RAM_CLR);

    (*wm2000).anc_mode = wm2000_anc_mode::ANC_BYPASS;
    dev_dbg(&mut (*i2c).dev, b"bypass enabled\n\0".as_ptr() as *const c_char);

    0
}

unsafe fn wm2000_exit_bypass(i2c: *mut i2c_client, analogue: c_int) -> c_int {
    let wm2000 = dev_get_drvdata(&mut (*i2c).dev) as *mut wm2000_priv;

    if WARN_ON((*wm2000).anc_mode != wm2000_anc_mode::ANC_BYPASS) != 0 {
        return -EINVAL;
    }

    wm2000_write(i2c, WM2000_REG_SYS_CTL1, 0);

    if analogue != 0 {
        wm2000_write(
            i2c,
            WM2000_REG_SYS_MODE_CNTRL,
            WM2000_MODE_ANA_SEQ_INCLUDE | WM2000_MODE_MOUSE_ENABLE | WM2000_MODE_THERMAL_ENABLE,
        );
    } else {
        wm2000_write(
            i2c,
            WM2000_REG_SYS_MODE_CNTRL,
            WM2000_MODE_MOUSE_ENABLE | WM2000_MODE_THERMAL_ENABLE,
        );
    }

    wm2000_write(i2c, WM2000_REG_SYS_CTL2, WM2000_RAM_SET);
    wm2000_write(i2c, WM2000_REG_SYS_CTL2, WM2000_ANC_INT_N_CLR);

    if wm2000_poll_bit(i2c, WM2000_REG_SYS_STATUS, WM2000_STATUS_MOUSE_ACTIVE as u8) == 0 {
        dev_err(&mut (*i2c).dev, b"Timed out waiting for MOUSE\n\0".as_ptr() as *const c_char);
        return -ETIMEDOUT;
    }

    (*wm2000).anc_mode = wm2000_anc_mode::ANC_ACTIVE;
    dev_dbg(&mut (*i2c).dev, b"MOUSE active\n\0".as_ptr() as *const c_char);

    0
}

unsafe fn wm2000_enter_standby(i2c: *mut i2c_client, analogue: c_int) -> c_int {
    let wm2000 = dev_get_drvdata(&mut (*i2c).dev) as *mut wm2000_priv;

    if WARN_ON((*wm2000).anc_mode != wm2000_anc_mode::ANC_ACTIVE) != 0 {
        return -EINVAL;
    }

    if analogue != 0 {
        wm2000_write(i2c, WM2000_REG_ANA_VMID_PD_TIME, 248 / 4);

        wm2000_write(
            i2c,
            WM2000_REG_SYS_MODE_CNTRL,
            WM2000_MODE_ANA_SEQ_INCLUDE | WM2000_MODE_THERMAL_ENABLE | WM2000_MODE_STANDBY_ENTRY,
        );
    } else {
        wm2000_write(
            i2c,
            WM2000_REG_SYS_MODE_CNTRL,
            WM2000_MODE_THERMAL_ENABLE | WM2000_MODE_STANDBY_ENTRY,
        );
    }

    if wm2000_poll_bit(i2c, WM2000_REG_SYS_STATUS, WM2000_STATUS_ANC_DISABLED as u8) == 0 {
        dev_err(
            &mut (*i2c).dev,
            b"Timed out waiting for ANC disable after 1ms\n\0".as_ptr() as *const c_char,
        );
        return -ETIMEDOUT;
    }

    if wm2000_poll_bit(i2c, WM2000_REG_ANC_STAT, WM2000_ANC_ENG_IDLE as u8) == 0 {
        dev_err(&mut (*i2c).dev, b"Timed out waiting for standby\n\0".as_ptr() as *const c_char);
        return -ETIMEDOUT;
    }

    wm2000_write(i2c, WM2000_REG_SYS_CTL1, WM2000_SYS_STBY);
    wm2000_write(i2c, WM2000_REG_SYS_CTL2, WM2000_RAM_CLR);

    (*wm2000).anc_mode = wm2000_anc_mode::ANC_STANDBY;
    dev_dbg(&mut (*i2c).dev, b"standby\n\0".as_ptr() as *const c_char);
    if analogue != 0 {
        dev_dbg(&mut (*i2c).dev, b"Analogue disabled\n\0".as_ptr() as *const c_char);
    }

    0
}

unsafe fn wm2000_exit_standby(i2c: *mut i2c_client, analogue: c_int) -> c_int {
    let wm2000 = dev_get_drvdata(&mut (*i2c).dev) as *mut wm2000_priv;

    if WARN_ON((*wm2000).anc_mode != wm2000_anc_mode::ANC_STANDBY) != 0 {
        return -EINVAL;
    }

    wm2000_write(i2c, WM2000_REG_SYS_CTL1, 0);

    if analogue != 0 {
        wm2000_write(i2c, WM2000_REG_ANA_VMID_PU_TIME, 248 / 4);

        wm2000_write(
            i2c,
            WM2000_REG_SYS_MODE_CNTRL,
            WM2000_MODE_ANA_SEQ_INCLUDE | WM2000_MODE_THERMAL_ENABLE | WM2000_MODE_MOUSE_ENABLE,
        );
    } else {
        wm2000_write(
            i2c,
            WM2000_REG_SYS_MODE_CNTRL,
            WM2000_MODE_THERMAL_ENABLE | WM2000_MODE_MOUSE_ENABLE,
        );
    }

    wm2000_write(i2c, WM2000_REG_SYS_CTL2, WM2000_RAM_SET);
    wm2000_write(i2c, WM2000_REG_SYS_CTL2, WM2000_ANC_INT_N_CLR);

    if wm2000_poll_bit(i2c, WM2000_REG_SYS_STATUS, WM2000_STATUS_MOUSE_ACTIVE as u8) == 0 {
        dev_err(&mut (*i2c).dev, b"Timed out waiting for MOUSE\n\0".as_ptr() as *const c_char);
        return -ETIMEDOUT;
    }

    (*wm2000).anc_mode = wm2000_anc_mode::ANC_ACTIVE;
    dev_dbg(&mut (*i2c).dev, b"MOUSE active\n\0".as_ptr() as *const c_char);
    if analogue != 0 {
        dev_dbg(&mut (*i2c).dev, b"Analogue enabled\n\0".as_ptr() as *const c_char);
    }

    0
}

type wm2000_mode_fn = Option<unsafe fn(i2c: *mut i2c_client, analogue: c_int) -> c_int>;

#[repr(C)]
struct anc_transition {
    source: wm2000_anc_mode,
    dest: wm2000_anc_mode,
    analogue: c_int,
    step: [wm2000_mode_fn; 2],
}

static mut anc_transitions: [anc_transition; 12] = [
    anc_transition {
        source: wm2000_anc_mode::ANC_OFF,
        dest: wm2000_anc_mode::ANC_ACTIVE,
        analogue: 1,
        step: [Some(wm2000_power_up), None],
    },
    anc_transition {
        source: wm2000_anc_mode::ANC_OFF,
        dest: wm2000_anc_mode::ANC_STANDBY,
        analogue: 0,
        step: [Some(wm2000_power_up), Some(wm2000_enter_standby)],
    },
    anc_transition {
        source: wm2000_anc_mode::ANC_OFF,
        dest: wm2000_anc_mode::ANC_BYPASS,
        analogue: 1,
        step: [Some(wm2000_power_up), Some(wm2000_enter_bypass)],
    },
    anc_transition {
        source: wm2000_anc_mode::ANC_ACTIVE,
        dest: wm2000_anc_mode::ANC_BYPASS,
        analogue: 1,
        step: [Some(wm2000_enter_bypass), None],
    },
    anc_transition {
        source: wm2000_anc_mode::ANC_ACTIVE,
        dest: wm2000_anc_mode::ANC_STANDBY,
        analogue: 1,
        step: [Some(wm2000_enter_standby), None],
    },
    anc_transition {
        source: wm2000_anc_mode::ANC_ACTIVE,
        dest: wm2000_anc_mode::ANC_OFF,
        analogue: 1,
        step: [Some(wm2000_power_down), None],
    },
    anc_transition {
        source: wm2000_anc_mode::ANC_BYPASS,
        dest: wm2000_anc_mode::ANC_ACTIVE,
        analogue: 1,
        step: [Some(wm2000_exit_bypass), None],
    },
    anc_transition {
        source: wm2000_anc_mode::ANC_BYPASS,
        dest: wm2000_anc_mode::ANC_STANDBY,
        analogue: 1,
        step: [Some(wm2000_exit_bypass), Some(wm2000_enter_standby)],
    },
    anc_transition {
        source: wm2000_anc_mode::ANC_BYPASS,
        dest: wm2000_anc_mode::ANC_OFF,
        analogue: 0,
        step: [Some(wm2000_exit_bypass), Some(wm2000_power_down)],
    },
    anc_transition {
        source: wm2000_anc_mode::ANC_STANDBY,
        dest: wm2000_anc_mode::ANC_ACTIVE,
        analogue: 1,
        step: [Some(wm2000_exit_standby), None],
    },
    anc_transition {
        source: wm2000_anc_mode::ANC_STANDBY,
        dest: wm2000_anc_mode::ANC_BYPASS,
        analogue: 1,
        step: [Some(wm2000_exit_standby), Some(wm2000_enter_bypass)],
    },
    anc_transition {
        source: wm2000_anc_mode::ANC_STANDBY,
        dest: wm2000_anc_mode::ANC_OFF,
        analogue: 0,
        step: [Some(wm2000_exit_standby), Some(wm2000_power_down)],
    },
];

unsafe fn wm2000_anc_transition(wm2000: *mut wm2000_priv, mode: wm2000_anc_mode) -> c_int {
    let i2c = (*wm2000).i2c;
    let mut i: usize = 0;
    let mut j: usize;
    let mut ret: c_int = 0;

    if (*wm2000).anc_mode == mode {
        return 0;
    }

    while i < anc_transitions.len() {
        if anc_transitions[i].source == (*wm2000).anc_mode && anc_transitions[i].dest == mode {
            break;
        }
        i += 1;
    }
    if i == anc_transitions.len() {
        dev_err(
            &mut (*i2c).dev,
            b"No transition for %d->%d\n\0".as_ptr() as *const c_char,
            (*wm2000).anc_mode as c_int,
            mode as c_int,
        );
        return -EINVAL;
    }

    /* Maintain clock while active */
    if anc_transitions[i].source == wm2000_anc_mode::ANC_OFF {
        ret = clk_prepare_enable((*wm2000).mclk);
        if ret != 0 {
            dev_err(&mut (*i2c).dev, b"Failed to enable MCLK: %d\n\0".as_ptr() as *const c_char, ret);
            return ret;
        }
    }

    j = 0;
    while j < anc_transitions[j].step.len() {
        if anc_transitions[i].step[j].is_none() {
            break;
        }
        ret = anc_transitions[i].step[j].unwrap()(i2c, anc_transitions[i].analogue);
        if ret != 0 {
            break;
        }
        j += 1;
    }

    if anc_transitions[i].dest == wm2000_anc_mode::ANC_OFF {
        clk_disable_unprepare((*wm2000).mclk);
    }

    ret
}

unsafe fn wm2000_anc_set_mode(wm2000: *mut wm2000_priv) -> c_int {
    let i2c = (*wm2000).i2c;
    let mode: wm2000_anc_mode;

    if (*wm2000).anc_eng_ena != 0 && (*wm2000).spk_ena != 0 {
        if (*wm2000).anc_active != 0 {
            mode = wm2000_anc_mode::ANC_ACTIVE;
        } else {
            mode = wm2000_anc_mode::ANC_BYPASS;
        }
    } else {
        mode = wm2000_anc_mode::ANC_STANDBY;
    }

    dev_dbg(
        &mut (*i2c).dev,
        b"Set mode %d (enabled %d, mute %d, active %d)\n\0".as_ptr() as *const c_char,
        mode as c_int,
        (*wm2000).anc_eng_ena,
        ((*wm2000).spk_ena == 0) as c_int,
        (*wm2000).anc_active,
    );

    wm2000_anc_transition(wm2000, mode)
}

unsafe fn wm2000_anc_mode_get(
    kcontrol: *mut snd_kcontrol,
    ucontrol: *mut snd_ctl_elem_value,
) -> c_int {
    let component = snd_kcontrol_chip(kcontrol) as *mut snd_soc_component;
    let wm2000 = dev_get_drvdata((*component).dev) as *mut wm2000_priv;

    (*ucontrol).value.integer.value[0] = (*wm2000).anc_active as libc_long;

    0
}

unsafe fn wm2000_anc_mode_put(
    kcontrol: *mut snd_kcontrol,
    ucontrol: *mut snd_ctl_elem_value,
) -> c_int {
    let component = snd_kcontrol_chip(kcontrol) as *mut snd_soc_component;
    let wm2000 = dev_get_drvdata((*component).dev) as *mut wm2000_priv;
    let anc_active: c_uint = (*ucontrol).value.integer.value[0] as c_uint;

    if anc_active > 1 {
        return -EINVAL;
    }

    mutex_lock(&mut (*wm2000).lock);

    (*wm2000).anc_active = anc_active;

    let ret = wm2000_anc_set_mode(wm2000);
    mutex_unlock(&mut (*wm2000).lock);
    ret
}

unsafe fn wm2000_speaker_get(
    kcontrol: *mut snd_kcontrol,
    ucontrol: *mut snd_ctl_elem_value,
) -> c_int {
    let component = snd_kcontrol_chip(kcontrol) as *mut snd_soc_component;
    let wm2000 = dev_get_drvdata((*component).dev) as *mut wm2000_priv;

    (*ucontrol).value.integer.value[0] = (*wm2000).spk_ena as libc_long;

    0
}

unsafe fn wm2000_speaker_put(
    kcontrol: *mut snd_kcontrol,
    ucontrol: *mut snd_ctl_elem_value,
) -> c_int {
    let component = snd_kcontrol_chip(kcontrol) as *mut snd_soc_component;
    let wm2000 = dev_get_drvdata((*component).dev) as *mut wm2000_priv;
    let val: c_uint = (*ucontrol).value.integer.value[0] as c_uint;

    if val > 1 {
        return -EINVAL;
    }

    mutex_lock(&mut (*wm2000).lock);

    (*wm2000).spk_ena = val;

    let ret = wm2000_anc_set_mode(wm2000);
    mutex_unlock(&mut (*wm2000).lock);
    ret
}

static wm2000_controls: [snd_kcontrol_new; 3] = [
    SOC_SINGLE(b"ANC Volume\0".as_ptr() as *const c_char, WM2000_REG_ANC_GAIN_CTRL, 0, 255, 0),
    SOC_SINGLE_BOOL_EXT(
        b"WM2000 ANC Switch\0".as_ptr() as *const c_char,
        0,
        Some(wm2000_anc_mode_get),
        Some(wm2000_anc_mode_put),
    ),
    SOC_SINGLE_BOOL_EXT(
        b"WM2000 Switch\0".as_ptr() as *const c_char,
        0,
        Some(wm2000_speaker_get),
        Some(wm2000_speaker_put),
    ),
];

unsafe fn wm2000_anc_power_event(
    w: *mut snd_soc_dapm_widget,
    _kcontrol: *mut snd_kcontrol,
    event: c_int,
) -> c_int {
    let component = snd_soc_dapm_to_component((*w).dapm);
    let wm2000 = dev_get_drvdata((*component).dev) as *mut wm2000_priv;

    mutex_lock(&mut (*wm2000).lock);

    if SND_SOC_DAPM_EVENT_ON(event) != 0 {
        (*wm2000).anc_eng_ena = 1;
    }

    if SND_SOC_DAPM_EVENT_OFF(event) != 0 {
        (*wm2000).anc_eng_ena = 0;
    }

    let ret = wm2000_anc_set_mode(wm2000);
    mutex_unlock(&mut (*wm2000).lock);
    ret
}

