// Original C condition: #ifdef CONFIG_PM; otherwise suspend/resume are NULL.
unsafe fn wm2000_suspend(component: *mut snd_soc_component) -> c_int {
    let wm2000 = dev_get_drvdata((*component).dev) as *mut wm2000_priv;

    wm2000_anc_transition(wm2000, wm2000_anc_mode::ANC_OFF)
}

unsafe fn wm2000_resume(component: *mut snd_soc_component) -> c_int {
    let wm2000 = dev_get_drvdata((*component).dev) as *mut wm2000_priv;

    wm2000_anc_set_mode(wm2000)
}

unsafe fn wm2000_readable_reg(_dev: *mut device, reg: c_uint) -> bool {
    match reg {
        WM2000_REG_SYS_START
        | WM2000_REG_ANC_GAIN_CTRL
        | WM2000_REG_MSE_TH1
        | WM2000_REG_MSE_TH2
        | WM2000_REG_SPEECH_CLARITY
        | WM2000_REG_SYS_WATCHDOG
        | WM2000_REG_ANA_VMID_PD_TIME
        | WM2000_REG_ANA_VMID_PU_TIME
        | WM2000_REG_CAT_FLTR_INDX
        | WM2000_REG_CAT_GAIN_0
        | WM2000_REG_SYS_STATUS
        | WM2000_REG_SYS_MODE_CNTRL
        | WM2000_REG_SYS_START0
        | WM2000_REG_SYS_START1
        | WM2000_REG_ID1
        | WM2000_REG_ID2
        | WM2000_REG_REVISON
        | WM2000_REG_SYS_CTL1
        | WM2000_REG_SYS_CTL2
        | WM2000_REG_ANC_STAT
        | WM2000_REG_IF_CTL
        | WM2000_REG_ANA_MIC_CTL
        | WM2000_REG_SPK_CTL => true,
        _ => false,
    }
}

static wm2000_regmap: regmap_config = regmap_config {
    reg_bits: 16,
    val_bits: 8,

    max_register: WM2000_REG_SPK_CTL,
    readable_reg: Some(wm2000_readable_reg),
};

unsafe fn wm2000_probe(component: *mut snd_soc_component) -> c_int {
    let wm2000 = dev_get_drvdata((*component).dev) as *mut wm2000_priv;

    /* This will trigger a transition to standby mode by default */
    wm2000_anc_set_mode(wm2000);

    0
}

unsafe fn wm2000_remove(component: *mut snd_soc_component) {
    let wm2000 = dev_get_drvdata((*component).dev) as *mut wm2000_priv;

    wm2000_anc_transition(wm2000, wm2000_anc_mode::ANC_OFF);
}

static soc_component_dev_wm2000: snd_soc_component_driver = snd_soc_component_driver {
    probe: Some(wm2000_probe),
    remove: Some(wm2000_remove),
    suspend: Some(wm2000_suspend),
    resume: Some(wm2000_resume),
    controls: wm2000_controls.as_ptr(),
    num_controls: wm2000_controls.len() as c_uint,
    dapm_widgets: wm2000_dapm_widgets.as_ptr(),
    num_dapm_widgets: wm2000_dapm_widgets.len() as c_uint,
    dapm_routes: wm2000_audio_map.as_ptr(),
    num_dapm_routes: wm2000_audio_map.len() as c_uint,
    idle_bias_on: 1,
    use_pmdown_time: 1,
};

unsafe fn wm2000_i2c_probe(i2c: *mut i2c_client) -> c_int {
    let mut wm2000: *mut wm2000_priv;
    let mut pdata: *mut wm2000_platform_data;
    let mut filename: *const c_char;
    let mut fw: *const firmware = ptr::null();
    let mut ret: c_int;
    let mut i: c_int;
    let mut reg: c_uint = 0;
    let mut id: u16;

    wm2000 = devm_kzalloc(
        &mut (*i2c).dev,
        core::mem::size_of::<wm2000_priv>(),
        GFP_KERNEL,
    ) as *mut wm2000_priv;
    if wm2000.is_null() {
        return -ENOMEM;
    }

    mutex_init(&mut (*wm2000).lock);

    dev_set_drvdata(&mut (*i2c).dev, wm2000 as *mut c_void);

    (*wm2000).regmap = devm_regmap_init_i2c(i2c, &wm2000_regmap);
    if IS_ERR((*wm2000).regmap as *const c_void) != 0 {
        ret = PTR_ERR((*wm2000).regmap as *const c_void) as c_int;
        dev_err(
            &mut (*i2c).dev,
            b"Failed to allocate register map: %d\n\0".as_ptr() as *const c_char,
            ret,
        );
        return ret;
    }

    i = 0;
    while i < WM2000_NUM_SUPPLIES as c_int {
        (*wm2000).supplies[i as usize].supply = wm2000_supplies[i as usize];
        i += 1;
    }

    ret = devm_regulator_bulk_get(
        &mut (*i2c).dev,
        WM2000_NUM_SUPPLIES as c_int,
        (*wm2000).supplies.as_mut_ptr(),
    );
    if ret != 0 {
        dev_err(&mut (*i2c).dev, b"Failed to get supplies: %d\n\0".as_ptr() as *const c_char, ret);
        return ret;
    }

    ret = regulator_bulk_enable(WM2000_NUM_SUPPLIES as c_int, (*wm2000).supplies.as_mut_ptr());
    if ret != 0 {
        dev_err(&mut (*i2c).dev, b"Failed to enable supplies: %d\n\0".as_ptr() as *const c_char, ret);
        return ret;
    }

    /* Verify that this is a WM2000 */
    ret = regmap_read((*wm2000).regmap, WM2000_REG_ID1, &mut reg);
    if ret != 0 {
        dev_err(&mut (*i2c).dev, b"Unable to read ID1: %d\n\0".as_ptr() as *const c_char, ret);
        return ret;
    }
    id = (reg << 8) as u16;
    ret = regmap_read((*wm2000).regmap, WM2000_REG_ID2, &mut reg);
    if ret != 0 {
        dev_err(&mut (*i2c).dev, b"Unable to read ID2: %d\n\0".as_ptr() as *const c_char, ret);
        return ret;
    }
    id |= (reg & 0xff) as u16;

    if id != 0x2000 {
        dev_err(
            &mut (*i2c).dev,
            b"Device is not a WM2000 - ID %x\n\0".as_ptr() as *const c_char,
            id as c_uint,
        );
        ret = -ENODEV;
        goto_err_supplies(i2c, wm2000, ret)
    } else {
        ret = regmap_read((*wm2000).regmap, WM2000_REG_REVISON, &mut reg);
        if ret != 0 {
            dev_err(&mut (*i2c).dev, b"Unable to read Revision: %d\n\0".as_ptr() as *const c_char, ret);
            return ret;
        }
        dev_info(&mut (*i2c).dev, b"revision %c\n\0".as_ptr() as *const c_char, reg + b'A' as c_uint);

        (*wm2000).mclk = devm_clk_get(&mut (*i2c).dev, b"MCLK\0".as_ptr() as *const c_char);
        if IS_ERR((*wm2000).mclk as *const c_void) != 0 {
            ret = PTR_ERR((*wm2000).mclk as *const c_void) as c_int;
            dev_err(&mut (*i2c).dev, b"Failed to get MCLK: %d\n\0".as_ptr() as *const c_char, ret);
            return goto_err_supplies(i2c, wm2000, ret);
        }

        filename = b"wm2000_anc.bin\0".as_ptr() as *const c_char;
        pdata = dev_get_platdata(&mut (*i2c).dev) as *mut wm2000_platform_data;
        if !pdata.is_null() {
            (*wm2000).speech_clarity = ((*pdata).speech_enh_disable == 0) as c_uint;

            if !(*pdata).download_file.is_null() {
                filename = (*pdata).download_file;
            }
        }

        ret = request_firmware(&mut fw, filename, &mut (*i2c).dev);
        if ret != 0 {
            dev_err(&mut (*i2c).dev, b"Failed to acquire ANC data: %d\n\0".as_ptr() as *const c_char, ret);
            return goto_err_supplies(i2c, wm2000, ret);
        }

        /* Pre-cook the concatenation of the register address onto the image */
        (*wm2000).anc_download_size = ((*fw).size + 2) as c_int;
        (*wm2000).anc_download = devm_kzalloc(
            &mut (*i2c).dev,
            (*wm2000).anc_download_size as usize,
            GFP_KERNEL,
        ) as *mut c_char;
        if (*wm2000).anc_download.is_null() {
            ret = -ENOMEM;
            release_firmware(fw);
            return goto_err_supplies(i2c, wm2000, ret);
        }

        *(*wm2000).anc_download.offset(0) = 0x80u8 as c_char;
        *(*wm2000).anc_download.offset(1) = 0x00u8 as c_char;
        memcpy(
            (*wm2000).anc_download.offset(2) as *mut c_void,
            (*fw).data as *const c_void,
            (*fw).size,
        );
        release_firmware(fw);

        (*wm2000).anc_eng_ena = 1;
        (*wm2000).anc_active = 1;
        (*wm2000).spk_ena = 1;
        (*wm2000).i2c = i2c;

        wm2000_reset(wm2000);

        ret = devm_snd_soc_register_component(
            &mut (*i2c).dev,
            &soc_component_dev_wm2000,
            ptr::null(),
            0,
        );

        goto_err_supplies(i2c, wm2000, ret)
    }
}

unsafe fn goto_err_supplies(i2c: *mut i2c_client, wm2000: *mut wm2000_priv, ret: c_int) -> c_int {
    regulator_bulk_disable(WM2000_NUM_SUPPLIES as c_int, (*wm2000).supplies.as_mut_ptr());
    ret
}

